async (page) => {
  const fs = require('fs');
  const https = require('http');
  const url = 'http://the-agent-company.com:8092/remote.php/dav/files/theagentcompany/Documents/command.txt';
  const auth = Buffer.from('theagentcompany:theagentcompany').toString('base64');
  return await new Promise((resolve, reject) => {
    https.get(url, { headers: { Authorization: 'Basic ' + auth } }, (res) => {
      let data = '';
      res.on('data', (chunk) => data += chunk);
      res.on('end', () => {
        fs.writeFileSync('/tmp/mcp-workspace/command.txt', data);
        resolve({ status: res.statusCode, length: data.length, content: data });
      });
    }).on('error', reject);
  });
}
